import { createClient } from "@supabase/supabase-js";
import { projectId, publicAnonKey } from "@/../utils/supabase/info";

// Supabase client for direct browser access (RLS-enforced) + Realtime.
// Config comes from the Figma Make autogenerated utils/supabase/info.tsx.
// Can be overridden via VITE_SUPABASE_URL and VITE_SUPABASE_ANON_KEY env vars.
export const supabaseUrl =
  import.meta.env.VITE_SUPABASE_URL || `https://${projectId}.supabase.co`;

const supabaseAnonKey =
  import.meta.env.VITE_SUPABASE_ANON_KEY || publicAnonKey;

export const supabase = createClient(supabaseUrl, supabaseAnonKey, {
  auth: {
    persistSession: false,
    autoRefreshToken: false,
  },
  realtime: {
    params: { eventsPerSecond: 10 },
  },
});
